<?php
declare(strict_types=1); require_once dirname(__DIR__).'/repositories/userPDO.php';
function validateRegistration(array $i):array{$name=trim((string)($i['full_name']??''));$email=strtolower(trim((string)($i['email']??'')));$password=(string)($i['password']??'');$confirm=(string)($i['confirm_password']??'');$role=(string)($i['role']??'');$e=[];if(mb_strlen($name)<2||mb_strlen($name)>120)$e[]='Enter a name from 2 to 120 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>254)$e[]='Enter a valid email address.';if(strlen($password)<12)$e[]='Password must contain at least 12 characters.';if($password!==$confirm)$e[]='Passwords do not match.';if(!in_array($role,['student','tutor'],true))$e[]='Choose Student or Tutor.';return[$e,compact('name','email','password','role')];}
function registerAccount(PDO $p,array $i):int{[$e,$d]=validateRegistration($i);if($e)throw new InvalidArgumentException(implode(' ',$e));return createUser($p,$d['name'],$d['email'],password_hash($d['password'],PASSWORD_DEFAULT),$d['role']);}
function authenticate(PDO $p,string $e,string $password):array|false{$u=findActiveUserByEmail($p,strtolower(trim($e)));if(!$u||!password_verify($password,$u['password_hash']))return false;if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT))updatePasswordHash($p,(int)$u['user_id'],password_hash($password,PASSWORD_DEFAULT));return['user_id'=>(int)$u['user_id'],'email'=>$u['email'],'display_name'=>$u['full_name'],'roles'=>loadRoles($p,(int)$u['user_id'])];}
function validateProfile(string $n,string $e):array{$err=[];$n=trim($n);$e=strtolower(trim($e));if(mb_strlen($n)<2||mb_strlen($n)>120)$err[]='Enter a name from 2 to 120 characters.';if(!filter_var($e,FILTER_VALIDATE_EMAIL)||mb_strlen($e)>254)$err[]='Enter a valid email address.';return[$err,$n,$e];}
function changeOwnPassword(PDO $p,int $id,string $current,string $new,string $confirm):void{$u=findUserWithHash($p,$id);if(!$u||!$u['active']||!password_verify($current,$u['password_hash']))throw new InvalidArgumentException('Current password is incorrect.');if(strlen($new)<12)throw new InvalidArgumentException('Password must contain at least 12 characters.');if($new!==$confirm)throw new InvalidArgumentException('New passwords do not match.');updatePasswordHash($p,$id,password_hash($new,PASSWORD_DEFAULT));}
function deleteAllowed(PDO $p,int $id):array{$roles=loadRoles($p,$id);if(in_array('admin',$roles,true)&&activeAdminCount($p)<=1)return[false,'The last active administrator cannot be deleted.'];if(userHasTutoringRecords($p,$id))return[false,'Deletion is blocked because related tutoring requests must be retained.'];return[true,''];}
